<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Water Molecule — Ball and Stick</title>

  <style>
    :root {
      color-scheme: dark;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
        "Segoe UI", sans-serif;
    }

    * {
      box-sizing: border-box;
    }

    html,
    body {
      width: 100%;
      height: 100%;
      margin: 0;
      overflow: hidden;
      background:
        radial-gradient(circle at 50% 42%, #26323d 0%, #111923 48%, #080d13 100%);
    }

    #stage {
      position: fixed;
      inset: 0;
    }

    canvas {
      display: block;
      width: 100%;
      height: 100%;
      touch-action: none;
      cursor: grab;
    }

    canvas:active {
      cursor: grabbing;
    }

    .info {
      position: fixed;
      top: clamp(20px, 4vw, 44px);
      left: clamp(20px, 4vw, 48px);
      z-index: 2;
      pointer-events: none;
      user-select: none;
    }

    .eyebrow {
      margin-bottom: 8px;
      color: #7f91a0;
      font-size: 11px;
      font-weight: 700;
      letter-spacing: 0.2em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      color: #f3f6f8;
      font-size: clamp(28px, 4vw, 48px);
      font-weight: 650;
      letter-spacing: -0.04em;
    }

    .subtitle {
      margin-top: 7px;
      color: #91a1ae;
      font-size: 13px;
    }

    .angle-card {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      margin-top: 20px;
      padding: 9px 13px;
      border: 1px solid rgba(174, 194, 211, 0.13);
      border-radius: 999px;
      background: rgba(15, 23, 31, 0.56);
      color: #b9c6d1;
      font-size: 12px;
      backdrop-filter: blur(12px);
    }

    .angle-card span {
      color: #ff6b75;
      font-size: 13px;
      font-weight: 700;
    }

    .hint {
      position: fixed;
      right: clamp(16px, 3vw, 36px);
      bottom: clamp(18px, 3vw, 32px);
      z-index: 2;
      color: #71818f;
      font-size: 11px;
      letter-spacing: 0.03em;
      pointer-events: none;
      user-select: none;
    }

    #reset {
      position: fixed;
      right: clamp(16px, 3vw, 36px);
      top: clamp(18px, 3vw, 32px);
      z-index: 3;
      padding: 9px 13px;
      border: 1px solid rgba(174, 194, 211, 0.16);
      border-radius: 9px;
      background: rgba(15, 23, 31, 0.64);
      color: #aebdc9;
      font: inherit;
      font-size: 11px;
      cursor: pointer;
      backdrop-filter: blur(12px);
    }

    #reset:hover {
      border-color: rgba(255, 255, 255, 0.3);
      color: white;
    }

    @media (max-width: 600px) {
      .hint {
        display: none;
      }

      .subtitle {
        max-width: 150px;
        line-height: 1.45;
      }
    }
  </style>
</head>

<body>
  <main id="stage" aria-label="Interactive three-dimensional water molecule"></main>

  <section class="info">
    <div class="eyebrow">Molecule Study</div>
    <h1>Water</h1>
    <div class="subtitle">Bent H₂O geometry</div>
    <div class="angle-card">
      <span>H—O—H</span>
      104.5°
    </div>
  </section>

  <button id="reset" type="button">Reset view</button>
  <div class="hint">Drag to orbit · Scroll to zoom</div>

  <script type="module">
    import * as THREE from
      "https://cdnjs.cloudflare.com/ajax/libs/three.js/0.160.0/three.module.min.js";

    const stage = document.getElementById("stage");
    const resetButton = document.getElementById("reset");

    // Renderer
    const renderer = new THREE.WebGLRenderer({
      antialias: true,
      alpha: true,
      powerPreference: "high-performance"
    });

    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.15;
    renderer.setClearColor(0x000000, 0);

    stage.appendChild(renderer.domElement);

    // Scene and camera
    const scene = new THREE.Scene();

    const camera = new THREE.PerspectiveCamera(
      36,
      window.innerWidth / window.innerHeight,
      0.1,
      100
    );

    const molecule = new THREE.Group();
    molecule.position.y = 0.15;
    scene.add(molecule);

    // Materials
    const oxygenMaterial = new THREE.MeshStandardMaterial({
      color: 0xff4d67,
      emissive: 0x3c0711,
      emissiveIntensity: 0.25,
      roughness: 0.28,
      metalness: 0.04
    });

    const hydrogenMaterial = new THREE.MeshStandardMaterial({
      color: 0xf7f8fb,
      roughness: 0.32,
      metalness: 0.02
    });

    const bondMaterial = new THREE.MeshStandardMaterial({
      color: 0x8794a0,
      roughness: 0.34,
      metalness: 0.55
    });

    const sleeveMaterial = new THREE.MeshStandardMaterial({
      color: 0xa7b3bf,
      roughness: 0.3,
      metalness: 0.62,
      side: THREE.DoubleSide
    });

    const oxygenPosition = new THREE.Vector3(0, 0, 0);

    // The H-O-H bond angle is approximately 104.5 degrees.
    const bondAngle = THREE.MathUtils.degToRad(104.5);
    const halfAngle = bondAngle / 2;
    const bondLength = 1.38;

    const hydrogenPositions = [
      new THREE.Vector3(
        Math.sin(halfAngle) * bondLength,
        Math.cos(halfAngle) * bondLength,
        0
      ),
      new THREE.Vector3(
        -Math.sin(halfAngle) * bondLength,
        Math.cos(halfAngle) * bondLength,
        0
      )
    ];

    // Helper: create a cylinder aligned between two points.
    function createCylinderBetween(start, end, radius, material, radialSegments = 20) {
      const direction = new THREE.Vector3().subVectors(end, start);
      const length = direction.length();

      const geometry = new THREE.CylinderGeometry(
        radius,
        radius,
        length,
        radialSegments,
        1,
        false
      );

      const mesh = new THREE.Mesh(geometry, material);
      mesh.position.copy(start).add(end).multiplyScalar(0.5);
      mesh.quaternion.setFromUnitVectors(
        new THREE.Vector3(0, 1, 0),
        direction.normalize()
      );

      return mesh;
    }

    // Helper: create an open sleeve with a shallow collar at its outer end.
    function createSleeve(atom, axis, radius, outerRing = true) {
      const sleeve = new THREE.Mesh(
        new THREE.CylinderGeometry(
          radius,
          radius,
          0.32,
          28,
          1,
          true
        ),
        sleeveMaterial
      );

      sleeve.position.copy(atom);
      sleeve.quaternion.setFromUnitVectors(
        new THREE.Vector3(0, 1, 0),
        axis.clone().normalize()
      );
      molecule.add(sleeve);

      if (!outerRing) return;

      const collar = new THREE.Mesh(
        new THREE.TorusGeometry(radius - 0.008, 0.025, 12, 36),
        sleeveMaterial
      );

      collar.position
        .copy(atom)
        .addScaledVector(axis, 0.165);

      collar.quaternion.setFromUnitVectors(
        new THREE.Vector3(0, 0, 1),
        axis.clone().normalize()
      );

      molecule.add(collar);
    }

    // Oxygen atom at the apex.
    const oxygen = new THREE.Mesh(
      new THREE.SphereGeometry(0.42, 48, 32),
      oxygenMaterial
    );
    oxygen.position.copy(oxygenPosition);
    molecule.add(oxygen);

    // Hydrogen atoms.
    const hydrogenAtoms = hydrogenPositions.map((position) => {
      const hydrogen = new THREE.Mesh(
        new THREE.SphereGeometry(0.225, 36, 24),
        hydrogenMaterial
      );
      hydrogen.position.copy(position);
      molecule.add(hydrogen);
      return hydrogen;
    });

    // Bond axes, pointing away from the central oxygen atom.
    const axes = hydrogenPositions.map((position) =>
      new THREE.Vector3().subVectors(position, oxygenPosition).normalize()
    );

    // Gray bonds.
    hydrogenPositions.forEach((end, index) => {
      const bond = createCylinderBetween(
        oxygenPosition,
        end,
        0.055,
        bondMaterial,
        18
      );
      molecule.add(bond);

      // Shallow sleeve wrapping around each atom.
      createSleeve(
        end,
        axes[index],
        0.235,
        true
      );

      // The oxygen atom has a wider sleeve.
      createSleeve(
        oxygenPosition,
        axes[index],
        0.365,
        false
      );
    });

    // Custom orbit controls; no external controls module is used.
    const target = new THREE.Vector3(0, 0.58, 0);
    const defaultView = {
      theta: 0.32,
      phi: 1.28,
      radius: 5.35
    };

    let theta = defaultView.theta;
    let phi = defaultView.phi;
    let radius = defaultView.radius;
    let dragging = false;
    let previousX = 0;
    let previousY = 0;

    function updateCamera() {
      const sinPhi = Math.sin(phi);

      camera.position.set(
        target.x + radius * sinPhi * Math.sin(theta),
        target.y + radius * Math.cos(phi),
        target.z + radius * sinPhi * Math.cos(theta)
      );

      camera.lookAt(target);
    }

    function resetView() {
      theta = defaultView.theta;
      phi = defaultView.phi;
      radius = defaultView.radius;
      updateCamera();
    }

    renderer.domElement.addEventListener("pointerdown", (event) => {
      dragging = true;
      previousX = event.clientX;
      previousY = event.clientY;
      renderer.domElement.setPointerCapture(event.pointerId);
    });

    renderer.domElement.addEventListener("pointermove", (event) => {
      if (!dragging) return;

      const deltaX = event.clientX - previousX;
      const deltaY = event.clientY - previousY;

      previousX = event.clientX;
      previousY = event.clientY;

      theta -= deltaX * 0.006;
      phi = THREE.MathUtils.clamp(phi - deltaY * 0.005, 0.22, Math.PI - 0.22);

      updateCamera();
    });

    function endDrag(event) {
      dragging = false;
      if (renderer.domElement.hasPointerCapture(event.pointerId)) {
        renderer.domElement.releasePointerCapture(event.pointerId);
      }
    }

    renderer.domElement.addEventListener("pointerup", endDrag);
    renderer.domElement.addEventListener("pointercancel", endDrag);

    renderer.domElement.addEventListener(
      "wheel",
      (event) => {
        event.preventDefault();
        radius = THREE.MathUtils.clamp(
          radius * Math.exp(event.deltaY * 0.001),
          3.35,
          9
        );
        updateCamera();
      },
      { passive: false }
    );

    renderer.domElement.addEventListener("dblclick", resetView);
    resetButton.addEventListener("click", resetView);

    // Responsive framing.
    function onResize() {
      const width = window.innerWidth;
      const height = window.innerHeight;
      const aspect = width / height;

      camera.aspect = aspect;
      camera.updateProjectionMatrix();

      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      renderer.setSize(width, height);

      if (aspect < 0.8) {
        radius = Math.max(radius, 6.25);
      }

      updateCamera();
    }

    window.addEventListener("resize", onResize);

    // Gentle floating motion.
    const clock = new THREE.Clock();

    renderer.setAnimationLoop(() => {
      const elapsed = clock.getElapsedTime();
      molecule.position.y = 0.15 + Math.sin(elapsed * 0.85) * 0.055;
      renderer.render(scene, camera);
    });

    onResize();
  </script>
</body>
</html>
